<?php session_start();if(!isset($_SESSION["admin_id"])){header("Location: ../login.php");exit;}require_once "../../config/database.php";function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,"UTF-8");}$data=$pdo->query("SELECT * FROM sawah ORDER BY id DESC")->fetchAll();$admin_root='..';$active='sawah';?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Data Lahan Sawah | Padi Seriti</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap"><link rel="stylesheet" href="../admin.css"></head><body class="admin-page"><div class="admin-shell"><?php include "../sidebar.php"; ?><main class="admin-main"><div class="topbar"><div><div class="eyebrow">DATA SPASIAL</div><h1>Data Lahan Sawah</h1></div><div class="top-actions"><a href="../import_geojson.php?type=sawah" class="btn-import"><i class="fa-solid fa-file-import"></i> Import GeoJSON</a><a href="tambah.php" class="btn-add"><i class="fa-solid fa-plus"></i> Tambah Data</a></div></div><div class="table-card"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>No</th><th>Nama Lahan</th><th>Luas</th><th>Varietas</th><th>Produksi</th><th>Kelompok Tani</th><th>Aksi</th></tr></thead><tbody><?php foreach($data as $i=>$row):?><tr><td><?=$i+1?></td><td><?=e($row["nama_lahan"]??"")?></td><td><?=e($row["luas"]??"")?></td><td><?=e($row["varietas"]??"")?></td><td><?=e($row["produksi"]??"")?></td><td><?=e($row["kelompok_tani"]??"")?></td><td class="actions"><a href="edit.php?id=<?=(int)$row['id']?>"><i class="fa-solid fa-pen"></i></a><a class="delete" href="hapus.php?id=<?=(int)$row['id']?>" onclick="return confirm('Hapus data ini?')"><i class="fa-solid fa-trash"></i></a></td></tr><?php endforeach;?><?php if(!$data):?><tr><td colspan="20" class="empty">Belum ada